import React, { useEffect } from 'react';
import { useGame } from '../contexts/GameContext';
import { COLORS } from '../utils/tetrominos';
import './GameBoard.css';

const GameBoard: React.FC = () => {
  const { state, dispatch } = useGame();

  useEffect(() => {
    const handleKeyPress = (event: KeyboardEvent) => {
      switch (event.key) {
        case 'ArrowLeft':
          dispatch({ type: 'MOVE_LEFT' });
          break;
        case 'ArrowRight':
          dispatch({ type: 'MOVE_RIGHT' });
          break;
        case 'ArrowDown':
          dispatch({ type: 'MOVE_DOWN' });
          break;
        case 'ArrowUp':
          dispatch({ type: 'ROTATE' });
          break;
        case ' ': // Space bar
          event.preventDefault();
          dispatch({ type: 'NEW_PIECE' });
          break;
      }
    };

    window.addEventListener('keydown', handleKeyPress);
    return () => {
      window.removeEventListener('keydown', handleKeyPress);
    };
  }, [dispatch]);

  useEffect(() => {
    if (!state.currentPiece && !state.gameOver) {
      dispatch({ type: 'NEW_PIECE' });
    }
  }, [state.currentPiece, state.gameOver, dispatch]);

  // Create a display board that includes both the fixed pieces and the current piece
  const displayBoard = state.board.map(row => [...row]);
  if (state.currentPiece) {
    state.currentPiece.shape.forEach((row, y) => {
      row.forEach((value, x) => {
        if (value) {
          const boardY = y + state.currentPiece!.position.y;
          const boardX = x + state.currentPiece!.position.x;
          if (boardY >= 0 && boardY < displayBoard.length && boardX >= 0 && boardX < displayBoard[0].length) {
            displayBoard[boardY][boardX] = 2; // Use 2 to distinguish current piece
          }
        }
      });
    });
  }

  return (
    <div className="game-container">
      <div className="game-board">
        {displayBoard.map((row, i) => (
          <div key={i} className="row">
            {row.map((cell, j) => (
              <div
                key={`${i}-${j}`}
                className={`cell ${cell ? 'filled' : ''} ${cell === 2 ? 'current' : ''}`}
                style={{
                  backgroundColor: cell === 2 && state.currentPiece
                    ? COLORS[state.currentPiece.type as keyof typeof COLORS]
                    : cell === 1
                    ? '#666'
                    : undefined
                }}
              />
            ))}
          </div>
        ))}
      </div>
      <div className="game-info">
        <div>Score: {state.score}</div>
        <div>Level: {state.level}</div>
        {state.gameOver && (
          <div className="game-over">
            Game Over!
            <button
              onClick={() => {
                dispatch({ type: 'NEW_PIECE' });
              }}
              className="restart-button"
            >
              Restart
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default GameBoard;
